using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class DockTimberRopeFinish{static DockTimberRopeFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("DockTimberRopeFinish.request"))return;File.Delete("DockTimberRopeFinish.request");try{var seen=new HashSet<Mesh>();int beam=0,ropes=0;foreach(string path in Enumerable.Range(1,6).Select(i=>"Assets/Scenes/Oasis/SouthBeach/Docking Pier "+i+".prefab").Concat(new[]{"Assets/Scenes/Oasis/YachtPortAtlas/Yatch Port Edge Details.prefab"})){var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;if(!seen.Add(mesh))continue;var p=mesh.vertices;var n=mesh.normals;var uv=mesh.uv;var flags=new List<Vector4>();mesh.GetUVs(1,flags);var ids=mesh.triangles;for(int k=0;k<ids.Length;k+=3){int a=ids[k],b=ids[k+1],c=ids[k+2];bool rope=flags[a].x==3;bool foundation=flags[a].x==1;bool wood=flags[a].x==0&&Mathf.Abs(n[a].y)<.65f;if(!rope&&!wood&&!foundation)continue;bool fascia=f.name.Contains("deck and foundation")&&wood&&(p[a].y+p[b].y+p[c].y)/3>-.6f;Vector3 axis;if(rope){var edges=new[]{p[b]-p[a],p[c]-p[a],p[c]-p[b]};var longest=edges.OrderByDescending(v=>v.sqrMagnitude).First();axis=Mathf.Abs(longest.x)>Mathf.Abs(longest.z)?Vector3.right:Vector3.forward;}else axis=fascia?(Mathf.Abs(n[a].x)>.5f?Vector3.forward:Vector3.right):Vector3.up;foreach(int j in new[]{a,b,c}){var q=p[j];float along=Vector3.Dot(q,axis);uv[j]=new Vector2(along*(rope?1.2f:.22f),fascia?q.y*.3f:rope?q.y*2:(q.x+q.z)*.6f);flags[j]=new Vector4(rope?3:0,flags[j].y,rope?0:1,0);}if(rope)ropes++;else beam++;}mesh.uv=uv;mesh.SetUVs(1,flags);EditorUtility.SetDirty(mesh);}PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var pier=scene.GetRootGameObjects().Single(g=>g.name=="South Beach Bays and Docking Piers").transform.GetChild(2);var target=pier.TransformPoint(new Vector3(0,.25f,17));var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,target+pier.TransformDirection(new Vector3(6,1.4f,-7)),target+pier.forward*5,"Timber-Pillars-Rope-Corrected"});var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/YachtPortAtlas/Shared Yacht Yard Atlas.mat");File.WriteAllText("FinalEnvironmentRoadReview/DockTimberRopeFinishReport.txt","SUCCESS beam faces="+beam+" rope faces="+ropes+"; seam-free beam grain from interior atlas wood region; vertical timber support grain; stable axis-aligned longitudinal rope coordinates; atlas mip gradients scaled to actual sample region; main deck top unchanged; shared atlas/prefabs retained; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/DockTimberRopeFinishReport.txt","FAILED "+e);Debug.LogException(e);}}}
